    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-ACCEPTANCE-RETENTION\',\'application\',\'current\',\'AI Poise сохраняет точные байты внешних входов и записи, необходимые для обязательных приёмки, повторной проверки, передачи, интеграции и других согласованных потребителей, вместе с идентичностью производителя, контрольной суммой и ссылкой на вход до завершения этих потребителей. До завершения обязательного использования отсутствие или изменение входа явно отклоняет соответствующую проверку; передача между исполнителями и промежуточная очистка не удаляют нужные материалы. После терминального статуса Task, подтверждённой поставки всех согласованных результатов и завершения обязательных потребителей вся принадлежащая Task рабочая папка подлежит удалению без скрытого архива. Материалы, отдельно согласованные как постоянный результат, предварительно поставляются вне рабочей папки Task. Сохранённая DB-история и квитанции фиксируют прошлые факты, но не подменяют удалённые байты и не доказывают новую проверку; новые действия не могут требовать уже удалённые материалы как постоянно доступные.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-ACCEPTANCE-RETENTION\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-ACTION-LIFECYCLE\',\'application\',\'current\',\'AI Poise связывает исполнение native action с текущим жизненным циклом Task. После согласованного restart текущий action принимает собственный точный план независимо от прошлых запусков, сохраняя неизменяемые исторические планы, результаты и аудит. Начатый текущий план остаётся неизменяемым; поддерживаемые повтор, передача владения и восстановление после прерывания соблюдают существующие правила Task и сохраняют рабочие исходники. Публичный контекст достоверно показывает текущий action после сохранения и повторного получения Task.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-ACTION-LIFECYCLE\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-AGENT-WORK-METRICS\',\'application\',\'future\',\'Приложение автоматически сохраняет фактически доступные метрики обычной работы агента, их единицы, источники и покрытие, различает повторные и новые наблюдения и предоставляет сохранённые сведения для последующего анализа. При частичных данных и сбоях сбора состояние метрик и применимое продолжение отражают известные факты, а основная операция сохраняет свой результат. При подключении владельца задач метрики дополняются доступными сведениями о соответствующей работе.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-AGENT-WORK-METRICS\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-CHECK-RESULT-CONTINUATION\',\'application\',\'current\',\'При завершении проверок приложение сохраняет их фактические результаты и доступный вывод. После прерывания или сбоя сохранения результата приложение предоставляет публичное действие для разрешения начатой операции и продолжения работы, включая ранее начатую проверку с неизвестным исходом. Повтор запроса с теми же входными данными возвращает сохранённый предметный результат либо завершает недостающие шаги с сохранением уже выполненных эффектов, истории, полномочий и согласованности рабочей области. Обработка одной проверки сохраняет доступность независимых задач. При отказе приложение сообщает установленное препятствие, затронутый объект, выполненные эффекты и точное доступное действие для устранения причины и продолжения.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-CHECK-RESULT-CONTINUATION\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-COMPLETE-INTERNAL-TOOL-OUTPUT\',\'application\',\'current\',\'AI Poise сохраняет полный ответ каждого инструмента для использования кодом других инструментов. Сокращённый вывод формирует общий владелец парсера перед передачей результата вызова инструмента агенту: для известной команды применяется настроенный специализированный профиль, для остальных — общий профиль. Внутренние инструменты не дублируют обрезание; данные для внутренней обработки и сохранения остаются полными.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-COMPLETE-INTERNAL-TOOL-OUTPUT\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-CONFIGURABLE-STORAGE-LAYOUT\',\'application\',\'future\',\'Пользователь задаёт расположение данных проекта и настроек общих редакторов. Приложение использует выбранное расположение данных проекта, а общие редакторы используют выбранные настройки независимо от расположения данных отдельного проекта.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-CONFIGURABLE-STORAGE-LAYOUT\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-CONFIGURATION-GUIDANCE\',\'application\',\'future\',\'Эксплуатационная документация содержит пример конфигурации, инструкцию заполнения и описание параметров настройки приложения. Пример соответствует работе приложения.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-CONFIGURATION-GUIDANCE\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-DOMAIN-LEXICON\',\'application\',\'future\',\'Реестр хранит определения предметных областей, сущностей и действий. Каждое имя принадлежит области. Требование связывается с именами через их области и может объединять несколько областей.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-DOMAIN-LEXICON\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-DRAFT-CONTINUATION\',\'application\',\'current\',\'После разрешённого изменения подготавливаемой задачи приложение позволяет получать её текущее состояние и продолжать подготовку, сохраняя цель, историю передач и рабочие материалы.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-DRAFT-CONTINUATION\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-ENVIRONMENT-COMMAND\',\'application\',\'future\',\'Приложение управляет своим окружением через внешнюю команду из явной рабочей конфигурации: стандартный механизм рендера подставляет параметры шаблона, инструмент использует локальный конфиг внутри папки Poise. Выбранный в конфигурации взаимозаменяемый плагин через общий интерфейс разбирает и анализирует полный результат, распознаёт ошибки, выполняет одну настроенную допустимую попытку исправления в пределах текущего запуска и передаёт неизвестную либо последующую ошибку агенту. Признак использованной попытки хранится только в памяти запуска. Рабочие конфиги исключены из VCS; заполненные обезличенные примеры, инструкция, описание интерфейса плагинов и полный справочник команд в скилле поставляются с документацией. Версия внешнего инструмента не является условием допуска запуска в Poise.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-ENVIRONMENT-COMMAND\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-GENERAL-CONTEXT-RECOVERY\',\'application\',\'future\',\'При сохранении и продолжении рабочего контекста приложение предоставляет сведения о состоянии рабочей копии, применимых инструкциях, учтённых чтениях и доступных проверках, сопоставляет сохранённое и актуальное состояние и автоматически выдаёт ограниченную сводку с адресами подробных материалов. Сведения о зарегистрированной работе включаются при подключённом источнике таких сведений. Повторное продолжение и разделение рабочих контекстов сохраняют соответствие данных, а недоступные сведения сопровождаются причиной и действием для продолжения.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-GENERAL-CONTEXT-RECOVERY\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-GENERAL-WORK-INSTRUCTIONS\',\'application\',\'future\',\'При работе с выбранными файлами настроенного проекта агент получает применимые правила и обязательные навыки с доступными инструкциями и основаниями выбора. Результат обновляется при изменении рабочих файлов или инструкций и различимо показывает обязательные материалы, рекомендации и пропуски. Возможность применяется к обычной работе, у которой нет зарегистрированной задачи или спринта.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-GENERAL-WORK-INSTRUCTIONS\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-HARNESS-POLICIES\',\'application\',\'current\',\'AI Poise defines general harness policies for file placement, handoff, code indexes and telemetry independently of optional Task/Sprint management.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-HARNESS-POLICIES\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-INDEPENDENT-DATA-WRITES\',\'application\',\'future\',\'Во время длительной подготовки изменения одних рабочих данных приложение выполняет операции над независимыми данными. Каждая успешная операция сохраняет изменения атомарно. При конфликте записи повтор исходного запроса сохраняет единственный согласованный результат.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-INDEPENDENT-DATA-WRITES\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-INDEPENDENT-TASK-MATERIALS\',\'application\',\'current\',\'Операции с материалами независимых задач выполняются независимо друг от друга. При конфликте конкретной записи приложение сохраняет принятые результаты и рабочие материалы, объясняет конфликт и позволяет продолжить допустимым повтором запроса. После частичного выполнения повтор сохраняет уже полученные эффекты и завершает недостающие действия с соблюдением полномочий и обязательных потребителей.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-INDEPENDENT-TASK-MATERIALS\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-INFRASTRUCTURE-READINESS\',\'application\',\'future\',\'Агент получает сведения о готовности настроенных инструментов и сервисов, причинах недоступности и действиях для восстановления при старте сессии и по явному запросу обновления.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-INFRASTRUCTURE-READINESS\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-INSPECTION-FINDING-SCOPE\',\'application\',\'current\',\'AI Poise определяет результат независимого осмотра и допустимые исправления по области проверяемого результата, сохраняет чужие открытые замечания и полную историю, а перед завершением задачи, публикацией и интеграцией проверяет глобальные незакрытые обязательства.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-INSPECTION-FINDING-SCOPE\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-INTEGRATED-WORKSPACE-RECONCILIATION\',\'application\',\'future\',\'После подтверждённого включения результата задачи в основную версию и завершения использования её рабочей области приложение сверяет актуальное владение и подтверждение освобождения ресурсов. Сверка освобождает оставшуюся привязку завершённой зависимой рабочей области с сохранением чужого и независимого владения, результатов и истории задачи. Очистка ресурсов выполняется после подтверждённой интеграции, а повтор сверки сохраняет единственный согласованный результат.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-INTEGRATED-WORKSPACE-RECONCILIATION\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-INTEGRATION-COMMIT-MESSAGE\',\'application\',\'current\',\'При локальной интеграции AI Poise отдельно сохраняет разрешение пользователя и заданное сообщение коммита; повтор и возобновление операции сохраняют эти сведения без подмены.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-INTEGRATION-COMMIT-MESSAGE\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-INTEGRATION-PREFLIGHT\',\'application\',\'current\',\'Перед включением принятого результата AI Poise проверяет, что выбранный репозиторий, рабочее дерево задачи и активная целевая ветка соответствуют месту назначения разрешённого действия. Несовпадение останавливает операцию до изменений Git, владения задачей и состояния интеграции; диагностика указывает фактическое и требуемое расположение и способ исправления. Поздние проверки публикации и повтор завершённой операции сохраняются.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-INTEGRATION-PREFLIGHT\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-INTEGRATION-SOURCE-PROVENANCE\',\'application\',\'current\',\'AI Poise выполняет интеграционные проверки на явно объявленных исходниках кандидата с согласованными cwd и привязками окружения. Отсутствующее или недопустимое происхождение исходников отклоняется до запуска проверки и публикации; явно объявленные внешние источники сохраняют свою семантику. Доказательства содержат разрешённое происхождение и связаны с точными commit/tree кандидата и определением метода. Публикация допускается только по соответствующим текущему кандидату доказательствам; повтор и обновление кандидата сохраняют историю и требуют необходимых актуальных доказательств.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-INTEGRATION-SOURCE-PROVENANCE\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-MAINTENANCE\',\'application\',\'current\',\'AI Poise owns generic environment maintenance, workspace recovery, and controlled release switching.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-MAINTENANCE\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-MAINTENANCE-CONSUMER\',\'application\',\'current\',\'Потребитель обслуживания окружения использует явно выбранные каталог и совместимую поставку инструмента с подтверждённым происхождением. Для требований каталога он получает достоверное состояние ресурсов, причину и рекомендации; разрешённые установка и исправление подтверждаются повторной исходной проверкой, а диагностика сохраняет состояние ресурсов. При отказе существующая работа пользователя сохраняется и доступен объяснённый способ продолжения.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-MAINTENANCE-CONSUMER\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-MATERIAL-READ-COVERAGE\',\'application\',\'future\',\'Приложение учитывает покрытие текущих версий материалов по пригодным результатам чтения в действительной сессии, выбранном проекте и рабочей копии. При подготовке чтения приложение сопоставляет запрошенные участки с покрытием, применяет настроенные пределы и правила повторов, различает ожидаемое чтение и чтение с пригодным результатом выполнения и выдаёт решение с причиной и действием для продолжения. При изменении материала или поколения контекста приложение предоставляет соответствующее состояние покрытия и возможность повторного чтения; при запросе состояния выдаёт ограниченную сводку покрытия и ожидающих результатов.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-MATERIAL-READ-COVERAGE\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-NAMED-PROJECT-CHECKS\',\'application\',\'future\',\'Приложение предоставляет именованные проверки и наборы шагов для выбранного проекта и рабочей копии, включая выбор и предварительный просмотр, упорядоченное выполнение, настроенные ограничения, различимые исходы, подтверждённое повторное использование результатов и полный доступный вывод. Возможность доступна при обычной работе без зарегистрированной задачи или спринта.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-NAMED-PROJECT-CHECKS\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-NATIVE-SESSION-CONTEXT\',\'application\',\'obsolete\',\'Публичные операции предоставляют контекст текущего сеанса и явно восстанавливают его после изменения настроек подключения с сохранением истории и владения работой\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-NATIVE-SESSION-CONTEXT\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-ORDINARY-OWNERSHIP-RELEASE\',\'application\',\'current\',\'Владелец исполняемой задачи явно освобождает её для дальнейшей работы через публичный интерфейс с указанием актуального состояния и причины. Приложение показывает изменение владения, сохраняет незавершённые проверки, результаты и рабочие материалы, согласованно освобождает зависимую рабочую область и сохраняет независимое владение. Повтор запроса возвращает исходный результат, а конфликт владения или актуальности получает объяснённый отказ с сохранением работы.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-ORDINARY-OWNERSHIP-RELEASE\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-PROJECT-FILE-FRAGMENTS\',\'application\',\'future\',\'Приложение предоставляет агенту указанные части файлов выбранного проекта в настроенных пределах, показывает фактические границы и идентичность содержимого для сравнения фрагментов, а при недоступном файле, неверном диапазоне или недопустимом пути сообщает причину отказа и действие для продолжения. Возможность доступна при обычной работе с проектом без зарегистрированной задачи или спринта.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-PROJECT-FILE-FRAGMENTS\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-PROJECT-PREFLIGHT\',\'application\',\'current\',\'AI Poise проверяет согласованность выбранной установки, проекта и хранилищ до изменения задач, показывает фактические идентификаторы и пути и возвращает причины отказа и публичные способы исправления без неявной подмены конфигурации.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-PROJECT-PREFLIGHT\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-REQUIREMENTS-REGISTRY-SELECTION\',\'application\',\'future\',\'Пользователь выбирает подготовленную базу требований для действующего проекта. Приложение использует выбранную базу, сохраняя её данные и доступность задач проекта. При одновременном изменении настроек выбора базы приложение сообщает о конфликте и сохраняет действующую конфигурацию и данные.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-REQUIREMENTS-REGISTRY-SELECTION\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-REQUIREMENTS-STORAGE\',\'application\',\'current\',\'Публичная настройка AI Poise принимает явно заданные Requirements DB и lock вне обслуживаемого репозитория либо внутри него, если Git подтверждает, что каждый путь игнорируется и не отслеживается. Отслеживаемый или неигнорируемый внутренний путь и невозможность подтвердить его Git-состояние приводят к явному отказу до создания или изменения хранилища. Проверка размещения применяется к существующим и отсутствующим путям. Requirements DB и lock не совпадают друг с другом и с Task DB и lock по разрешённым путям или существующим физическим файлам.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-REQUIREMENTS-STORAGE\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-RESOURCE-DESCRIPTION\',\'application\',\'future\',\'Для каждого ресурса определены назначение, потребители, принадлежность установке или проекту, текущее и рекомендуемое размещение, возможность настройки.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-RESOURCE-DESCRIPTION\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-RESOURCE-LIFECYCLE\',\'application\',\'future\',\'Для материалов задач, общих материалов спринта и ресурсов сессии определены сроки хранения и очистка. Остатки завершённой работы без дальнейшего назначения удаляются без создания сохраняющих их копий.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-RESOURCE-LIFECYCLE\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-RESOURCE-SEPARATION\',\'application\',\'future\',\'Проектные данные отделены друг от друга и от общих ресурсов установки; обязательные ограничения отделены от рекомендаций.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-RESOURCE-SEPARATION\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-RESTART-AUTO\',\'application\',\'current\',\'После разрешённого изменения договора перезапущенной задачи AI Poise автоматически повторно проверяет ранее принятые этапы по действующим требованиям и продвигает задачу до первого неподтверждённого этапа, сохраняя историю и рабочие материалы.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-RESTART-AUTO\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-RESTART-CONTRACT-REVISION\',\'application\',\'current\',\'AI Poise применяет разрешённую ревизию договора перезапущенной задачи без фиктивных проверок, сохраняя историю требований и доказательств.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-RESTART-CONTRACT-REVISION\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-RESTART-HISTORICAL-CHECKS\',\'application\',\'current\',\'AI Poise допускает разрешённый перезапуск незавершённой задачи после штатной смены владельца с атомарным архивированием остановленной исторической попытки проверок, сохраняя её исходную идентичность и неопределённый результат. Архивирование требует подтверждённого завершения процессов и непрерывной истории только событий владения; оно не разрешает повторное исполнение, успешную проверку или обход текущего владения.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-RESTART-HISTORICAL-CHECKS\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-RESTART-TRANSFER\',\'application\',\'current\',\'AI Poise передаёт перезапущенную задачу между агентами, сохраняя владение, рабочие материалы, замечания и происхождение результатов.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-RESTART-TRANSFER\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-RESULT-INTEGRATION\',\'application\',\'current\',\'AI Poise integrates completed Task results using the authoritative current eligible verification registry and complete successful evidence bound to the exact candidate, method definitions and Task requirement provenance. Publication, retry and recovery preserve immutable accepted source and audit, existing owned workspace resources, foreign WIP and idempotent request identity; missing or invalid proof requires fresh checks before publication.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-RESULT-INTEGRATION\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-REVIEW-RELEASE-CONTINUATION\',\'application\',\'future\',\'После независимого осмотра и освобождения владения приложение позволяет назначенному исполнителю продолжить разрешённую доработку актуального результата с сохранением рабочих материалов, замечаний, истории и подтверждённых результатов. При изменении исходников, чужом владении или неизвестном исходе внешнего действия приложение сохраняет работу и объясняет причину остановки и доступный путь продолжения.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-REVIEW-RELEASE-CONTINUATION\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-SPRINT-UNPUBLISH\',\'application\',\'current\',\'AI Poise позволяет вернуть допустимый опубликованный Sprint в редактируемый черновик, сохраняя идентичность участников, договоры Task, результаты, историю и рабочие материалы. Недопустимые состояния отклоняются без изменений; разрешённый пересмотр и повторная публикация проходят через публичные операции с аудитом и точным повтором.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-SPRINT-UNPUBLISH\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-STAGE-CRITERIA\',\'application\',\'future\',\'Приложение применяет согласованную редакцию требований, DoR и DoD этапа и допускает её уточнение в соответствии с типом этапа, полномочиями участника и состоянием выполнения.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-STAGE-CRITERIA\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-STAGE-RESULT-HANDOFF\',\'application\',\'future\',\'При передаче результата этапа назначенный участник одним обращением сохраняет результат и его доказательства, выполняет допустимое продвижение работы и освобождает владение для следующего участника. Передача соблюдает полномочия участников, независимость проверки и отдельные условия приёмки и публикации результата. При препятствии или повторе обращения приложение сохраняет уже выполненные действия и показывает фактический исход и доступное продолжение.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-STAGE-RESULT-HANDOFF\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-TASK-CONTRACTS\',\'application\',\'obsolete\',\'AI Poise rejects contradictory Task/rework mutability boundaries and invalid stage graphs before execution.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-TASK-CONTRACTS\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-TASK-PLANNING-CONFIG\',\'application\',\'future\',\'AI Poise supports explicitly configured operator task planning from registered starters while preserving existing Task contracts.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-TASK-PLANNING-CONFIG\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-TASK-PROOF-FILES\',\'application\',\'current\',\'При предъявлении результата задачи приложение предоставляет перечень отдельных файлов доказательств с их назначением и связью с проверяемыми требованиями и решениями. Каждое доказательство сохраняет своё расположение, включая появление дополнительных доказательств; после отклонения или установления недостоверности исправленный файл доступен следующей проверке по тому же расположению. Проверка читает предъявленное текущее содержимое и объясняет отсутствие файла или несоответствие его принадлежности задаче.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-TASK-PROOF-FILES\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-TERMINAL-RESULT-CLEANUP\',\'application\',\'current\',\'Приложение фиксирует согласованное постоянное назначение результатов задачи и подтверждает их поставку. После перехода задачи в терминальное состояние, поставки согласованных результатов и завершения обязательных потребителей приложение удаляет принадлежащую задаче рабочую папку вместе со служебными материалами. Правило применяется к самостоятельным задачам и участникам спринта. При отмене согласуется сохраняемый результат либо завершение без поставляемого результата. Приложение сообщает состояние поставки и очистки и поддерживает продолжение прерванной операции. Постоянные результаты, материалы других задач, общие материалы спринта, рабочие конфигурации и действующая установка сохраняются. Публичное чтение терминальной задачи и повтор завершённых операций отображают исторические результаты, идентичность задачи и квитанции поставки и очистки.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-TERMINAL-RESULT-CLEANUP\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-VERIFICATION-REGISTRY\',\'application\',\'current\',\'AI Poise preserves authoritative Task verification definitions, schedules, classification, provenance, registry revision and immutable audit/request history during authorised restart and readiness. Explicitly authorised registry changes preserve unchanged entries and historical layers, do not resurrect deleted methods, and do not validate incompatible or stale execution evidence.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-VERIFICATION-REGISTRY\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-WORKING-RESULT-PLACEMENT\',\'application\',\'future\',\'Агент получает по политике выбранного проекта категорию рабочего результата, допустимое размещение и проверку выбранного места с учётом действительных разрешений и предоставленного владельца хранения\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-WORKING-RESULT-PLACEMENT\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-AIP-WORKSPACE-RECOVERY\',\'application\',\'future\',\'Рабочее состояние задачи переносимо между окружениями без включения полных исходников в пакет передачи. Необходимые материалы и сведения о проверках сохраняются и размещаются совместимо с принимающей системой. Развёртывание сообщает успех или неуспех; при успехе задача читается, её состояние валидно и доступно продолжение с сохранённого этапа без автоматического выполнения этапов. Повторные проверки используют текущие версии систем, а сохранённые коммиты и конфиги позволяют анализировать различия результатов.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-AIP-WORKSPACE-RECOVERY\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-CODEX-TOOL-USAGE-ANALYSIS\',\'application\',\'current\',\'Приложение анализирует записи сессий Codex и предоставляет проверяемый перечень инструментов и статистику частоты вызовов, исходов и объёма доставленной и исходной выдачи, раздельно по проектам, представлению, источникам и периодам.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-CODEX-TOOL-USAGE-ANALYSIS\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-POISE-COMMIT-RULES\',\'application\',\'future\',\'При сохранении изменений проекта применимые правила задают оформление сообщения и смысловую группировку результата, разграничивая подтверждение качества работы, проверку состава сохраняемого изменения и интеграцию результата.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-POISE-COMMIT-RULES\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-POISE-HARNESS-ARCHITECTURE\',\'application\',\'current\',\'Харнесс обрабатывает события через единую настраиваемую цепочку обработчиков с установленным порядком и правилами синхронных и асинхронных действий; общий механизм не зависит от обязательного наличия задачи или конкретного проекта. Исполняемый код версионируется, рабочие настройки и данные исключены из контроля версий, а применимые правила описаны тематическими политиками.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-POISE-HARNESS-ARCHITECTURE\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-POISE-HARNESS-RESEARCH\',\'application\',\'future\',\'Исследовательские материалы по средствам разработки связывают рассмотренные сценарии с фактическими потребителями и результатами, показывают действующее покрытие и обосновывают рекомендации по общим механизмам и отдельным средствам управления заданиями.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-POISE-HARNESS-RESEARCH\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-POISE-SOURCE-INDEX\',\'application\',\'future\',\'Подключаемое средство поиска поддерживает актуальные индексированные сведения выбранной рабочей копии после успешного сохранения изменений и сообщает о состоянии, от которого зависит достоверность поиска.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-POISE-SOURCE-INDEX\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'APP-STRIDE-PROJECT-OPERATIONS\',\'application\',\'current\',\'Операции выбранного проекта выполняются с его действующими настройками, независимо заданным размещением инструментария и рабочих данных и явно выбранной версией инструментария; непригодные обязательные настройки приводят к объяснённому отказу с сохранением существующей работы.\');', 'DELETE FROM "requirements" WHERE "id" IS \'APP-STRIDE-PROJECT-OPERATIONS\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'ERP-APP-REQUIREMENTS-MIGRATIONS-001\',\'application\',\'future\',\'Приложение применяет и откатывает SQL-миграции БД требований стандартным минимальным Python-инструментом.\');', 'DELETE FROM "requirements" WHERE "id" IS \'ERP-APP-REQUIREMENTS-MIGRATIONS-001\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'ERP-APP-REQUIREMENTS-MIGRATIONS-002\',\'application\',\'future\',\'Начальная схема задаётся отдельной буквальной DDL-миграцией, исходные данные — отдельной буквальной DML-миграцией; обратные действия также заданы прямым SQL.\');', 'DELETE FROM "requirements" WHERE "id" IS \'ERP-APP-REQUIREMENTS-MIGRATIONS-002\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'ERP-APP-REQUIREMENTS-MIGRATIONS-003\',\'application\',\'future\',\'Команда по явному выбору требований создаёт самостоятельную миграцию переноса из старой БД, сохраняя идентификаторы и связи; совпадения не дублируются, расхождения отклоняются явно.\');', 'DELETE FROM "requirements" WHERE "id" IS \'ERP-APP-REQUIREMENTS-MIGRATIONS-003\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'ERP-APP-REQUIREMENTS-MIGRATIONS-004\',\'application\',\'future\',\'Старая БД и существующие данные сохраняются во время перехода, действующие агенты могут продолжать разрешённые записи; удаление возможно только после прекращения записей и сверки переноса.\');', 'DELETE FROM "requirements" WHERE "id" IS \'ERP-APP-REQUIREMENTS-MIGRATIONS-004\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'ERP-APP-REQUIREMENTS-MIGRATIONS-005\',\'application\',\'future\',\'Правила приложения закрепляют независимость миграций от прикладного кода, раздельные DDL/DML, явный накат/откат и порядок переноса агентами.\');', 'DELETE FROM "requirements" WHERE "id" IS \'ERP-APP-REQUIREMENTS-MIGRATIONS-005\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'ERP-APP-REQUIREMENTS-MIGRATIONS-006\',\'application\',\'future\',\'Накат, повторный запуск, отказ, перенос и откат сохраняют проверяемую целостность, значения и связи; точные предусловия безопасного отката документированы.\');', 'DELETE FROM "requirements" WHERE "id" IS \'ERP-APP-REQUIREMENTS-MIGRATIONS-006\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'ERP-SYS-REQUIREMENTS-MIGRATIONS\',\'system\',\'future\',\'Требования ERP управляются приложением управления задачами; схема и перенос данных воспроизводятся прямыми SQL-миграциями с накатом и откатом, а старая БД сохраняется до прекращения записи действующими агентами.\');', 'DELETE FROM "requirements" WHERE "id" IS \'ERP-SYS-REQUIREMENTS-MIGRATIONS\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'SYS-AGENT-CURRENT-SOURCE-RELATIONSHIPS\',\'system\',\'future\',\'При поиске связей в исходниках агент получает сведения из актуальных данных выбранной рабочей копии.\');', 'DELETE FROM "requirements" WHERE "id" IS \'SYS-AGENT-CURRENT-SOURCE-RELATIONSHIPS\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'SYS-AGENT-MATERIAL-READ-COVERAGE\',\'system\',\'future\',\'Агент получает актуальные сведения о прочитанных частях материалов в своём рабочем контексте и предусмотренную правилами возможность повторного чтения необходимых частей.\');', 'DELETE FROM "requirements" WHERE "id" IS \'SYS-AGENT-MATERIAL-READ-COVERAGE\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'SYS-AGENT-NAMED-PROJECT-CHECKS\',\'system\',\'future\',\'При работе над проектом агент выбирает настроенную проверку или набор шагов, получает выполнение по заданным условиям и достоверные сохранённые результаты для оценки исхода.\');', 'DELETE FROM "requirements" WHERE "id" IS \'SYS-AGENT-NAMED-PROJECT-CHECKS\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'SYS-AGENT-PROJECT-FILE-FRAGMENTS\',\'system\',\'future\',\'Агент получает запрошенные части файлов выбранного проекта с фактическими границами, ограничениями объёма и сведениями об изменении содержимого; при невозможности чтения получает причину и действие для продолжения.\');', 'DELETE FROM "requirements" WHERE "id" IS \'SYS-AGENT-PROJECT-FILE-FRAGMENTS\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'SYS-AGENT-PROJECT-INSTRUCTIONS\',\'system\',\'future\',\'При подготовке работы с материалами проекта исполнитель получает применимые к этой работе правила и необходимые обязательные инструкции.\');', 'DELETE FROM "requirements" WHERE "id" IS \'SYS-AGENT-PROJECT-INSTRUCTIONS\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'SYS-AGENT-RESULT-PROOF\',\'system\',\'current\',\'При независимой проверке результата проверяющий получает отдельные доказательства с ясным назначением, принадлежностью и актуальным предъявленным содержимым.\');', 'DELETE FROM "requirements" WHERE "id" IS \'SYS-AGENT-RESULT-PROOF\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'SYS-AGENT-SESSION-CONTEXT\',\'system\',\'obsolete\',\'Агенты управляют работой в контексте собственного подлинного сеанса и явно выбранного проекта\');', 'DELETE FROM "requirements" WHERE "id" IS \'SYS-AGENT-SESSION-CONTEXT\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'SYS-AGENT-TOOL-OUTPUT-ANALYSIS\',\'system\',\'current\',\'Статистика использования инструментов и объёма их выдачи позволяет выбирать способы представления полезной информации агентам, сохраняя возможность получить расширенный и полный вывод.\');', 'DELETE FROM "requirements" WHERE "id" IS \'SYS-AGENT-TOOL-OUTPUT-ANALYSIS\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'SYS-AGENT-WORK-CONTEXT-CONTINUITY\',\'system\',\'future\',\'После сокращения контекста и возобновления работы агент получает краткие актуальные сведения о текущей работе и материалах, необходимые для её продолжения.\');', 'DELETE FROM "requirements" WHERE "id" IS \'SYS-AGENT-WORK-CONTEXT-CONTINUITY\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'SYS-AGENT-WORK-METRICS\',\'system\',\'future\',\'Метрики использования инструментов, контекста, токенов и времени при обычной работе агента сохраняются с их происхождением и границами наблюдения для последующего анализа эффективности.\');', 'DELETE FROM "requirements" WHERE "id" IS \'SYS-AGENT-WORK-METRICS\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'SYS-AGENT-WORKING-RESULT-PLACEMENT\',\'system\',\'future\',\'Рабочие результаты автоматизированной разработки получают согласованное размещение по их назначению, получателю и сроку использования\');', 'DELETE FROM "requirements" WHERE "id" IS \'SYS-AGENT-WORKING-RESULT-PLACEMENT\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'SYS-AIP-CONFIGURATION-GUIDANCE\',\'system\',\'future\',\'Пользователь настраивает приложение по эксплуатационной документации, соответствующей работе приложения.\');', 'DELETE FROM "requirements" WHERE "id" IS \'SYS-AIP-CONFIGURATION-GUIDANCE\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'SYS-AIP-DOMAIN-LANGUAGE\',\'system\',\'current\',\'В пределах одной предметной области сущности и действия имеют согласованные бизнес-имена и имена для кода, одинаковые для всех использующих их приложений и библиотек. В разных областях одинаковые имена могут иметь разный смысл.\');', 'DELETE FROM "requirements" WHERE "id" IS \'SYS-AIP-DOMAIN-LANGUAGE\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'SYS-AIP-EXPLICIT-ENVIRONMENT\',\'system\',\'current\',\'Приложение выполняет операции только в явно выбранном и пригодном окружении; при отказе сохраняет существующую работу пользователя и объясняет причину и допустимый способ восстановления.\');', 'DELETE FROM "requirements" WHERE "id" IS \'SYS-AIP-EXPLICIT-ENVIRONMENT\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'SYS-AIP-HARNESS\',\'system\',\'obsolete\',\'AI Poise provides safe project-independent development automation.\');', 'DELETE FROM "requirements" WHERE "id" IS \'SYS-AIP-HARNESS\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'SYS-AIP-INDEPENDENT-DATA-OPERATIONS\',\'system\',\'future\',\'Независимые операции с рабочими данными сохраняют доступность друг для друга, а одновременные изменения сохраняют согласованность данных.\');', 'DELETE FROM "requirements" WHERE "id" IS \'SYS-AIP-INDEPENDENT-DATA-OPERATIONS\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'SYS-AIP-INSTALLATION-STORAGE\',\'system\',\'current\',\'Рабочие данные AI Poise размещаются по явно заданным путям, отдельно от версионируемого кода продукта и самостоятельных хранилищ других назначений.\');', 'DELETE FROM "requirements" WHERE "id" IS \'SYS-AIP-INSTALLATION-STORAGE\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'SYS-AIP-INTEGRATION-PROVENANCE\',\'system\',\'current\',\'Включение изменений в основную версию сохраняет основание разрешённого действия и назначение внесённых изменений как отдельные сведения.\');', 'DELETE FROM "requirements" WHERE "id" IS \'SYS-AIP-INTEGRATION-PROVENANCE\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'SYS-AIP-RESOURCE-DESCRIPTION\',\'system\',\'future\',\'Для каждого ресурса определены назначение, потребители, принадлежность установке или проекту, текущее и рекомендуемое размещение, возможность настройки.\');', 'DELETE FROM "requirements" WHERE "id" IS \'SYS-AIP-RESOURCE-DESCRIPTION\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'SYS-AIP-RESOURCE-LIFECYCLE\',\'system\',\'future\',\'Для материалов задач, общих материалов спринта и ресурсов сессии определены сроки хранения и очистка. Остатки завершённой работы без дальнейшего назначения удаляются без создания сохраняющих их копий.\');', 'DELETE FROM "requirements" WHERE "id" IS \'SYS-AIP-RESOURCE-LIFECYCLE\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'SYS-AIP-RESOURCE-SEPARATION\',\'system\',\'future\',\'Проектные данные отделены друг от друга и от общих ресурсов установки; обязательные ограничения отделены от рекомендаций.\');', 'DELETE FROM "requirements" WHERE "id" IS \'SYS-AIP-RESOURCE-SEPARATION\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'SYS-AIP-STAGE-CRITERIA\',\'system\',\'future\',\'Участники работы уточняют критерии результата этапа при проектировании и выполняют этап по согласованным критериям.\');', 'DELETE FROM "requirements" WHERE "id" IS \'SYS-AIP-STAGE-CRITERIA\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'SYS-AIP-TASK-CONTINUITY\',\'system\',\'current\',\'Работа над задачей продолжается после перезапуска и смены исполнителя без потери истории, результатов и рабочих материалов.\');', 'DELETE FROM "requirements" WHERE "id" IS \'SYS-AIP-TASK-CONTINUITY\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'SYS-AIP-TASK-RESULT-DELIVERY\',\'system\',\'current\',\'Результат завершённой или отменённой задачи сохраняется для заказчика в явно согласованном постоянном месте. Временные рабочие материалы задачи удаляются только после подтверждённой поставки согласованного результата и завершения обязательных использующих их действий; удаление не повреждает постоянные результаты, чужую работу и достоверную историю.\');', 'DELETE FROM "requirements" WHERE "id" IS \'SYS-AIP-TASK-RESULT-DELIVERY\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'SYS-AIP-TOOL-OUTPUT-AUDIENCE\',\'system\',\'current\',\'Только агенты получают суммаризированный вывод инструментов.\');', 'DELETE FROM "requirements" WHERE "id" IS \'SYS-AIP-TOOL-OUTPUT-AUDIENCE\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'SYS-DEVELOPMENT-TOOL-DECISIONS\',\'system\',\'future\',\'Решения о применении средств разработки опираются на проверенные сведения об их назначении, фактическом использовании и уже доступных возможностях.\');', 'DELETE FROM "requirements" WHERE "id" IS \'SYS-DEVELOPMENT-TOOL-DECISIONS\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'SYS-HARNESS-ARCHITECTURE\',\'system\',\'current\',\'Средства сопровождения работы агента соблюдают согласованную архитектуру обработки событий и независимость от управляемого проекта.\');', 'DELETE FROM "requirements" WHERE "id" IS \'SYS-HARNESS-ARCHITECTURE\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'SYS-PROJECT-CHANGE-HISTORY\',\'system\',\'future\',\'История изменений проекта отражает связанные результаты работы, их эффект и назначение.\');', 'DELETE FROM "requirements" WHERE "id" IS \'SYS-PROJECT-CHANGE-HISTORY\';'),
    step('INSERT INTO "requirements"("id","level","status","text") VALUES(\'SYS-VERIFICATION-CONTRACT-PREPARATION\',\'system\',\'future\',\'При подготовке и продолжении работы определения и расписание проверок сохраняют согласованность и происхождение. При отклонении непригодных входных данных система указывает нарушенное условие и способ исправления.\');', 'DELETE FROM "requirements" WHERE "id" IS \'SYS-VERIFICATION-CONTRACT-PREPARATION\';'),
